39 // Is2Pow(n) is true iff n==2^k for some k>=0.
40 predicate Is2Pow( n: int )
41     decreases n;
42 {
43     if n < 1 then
44         false
45     else if n == 1 then
46         true
47     else
48         n%2 == 0 && Is2Pow(n/2)
49 }
